// Riki 剧情工作台版本加载器
// 发布地址已经固定，日常更新只改下一行。
const RIKI_VERSION = '1.3.1';
const RIKI_RELEASE_BASE = 'http://127.0.0.1:8178/releases';

(async function loadRikiStoryWorkbench() {
  const hostWindow = (() => {
    try { return window.parent && window.parent !== window ? window.parent : window; } catch (_) { return window; }
  })();
  const statusKey = '__RIKI_STORY_WORKBENCH_LOADER_STATUS__';
  const url = RIKI_RELEASE_BASE.startsWith('http://127.0.0.1')
    ? `${RIKI_RELEASE_BASE}/${RIKI_VERSION}/riki-workbench.js`
    : `${RIKI_RELEASE_BASE}@v${RIKI_VERSION}/dist/releases/${RIKI_VERSION}/riki-workbench.js`;
  hostWindow[statusKey] = { status: 'loading', version: RIKI_VERSION, url, startedAt: new Date().toISOString() };
  try {
    const module = await import(url);
    if (typeof module.start !== 'function') throw new Error('远程 bundle 未导出 start()');
    const api = await module.start({ startWindow: window, hostWindow });
    if (api?.version !== RIKI_VERSION) throw new Error(`版本校验失败：请求 ${RIKI_VERSION}，实际 ${api?.version || "unknown"}`);
    hostWindow[statusKey] = { status: 'ready', version: RIKI_VERSION, url, readyAt: new Date().toISOString() };
  } catch (error) {
    const message = `Riki 剧情工作台 ${RIKI_VERSION} 加载失败：${error?.message || error}`;
    hostWindow[statusKey] = { status: 'failed', version: RIKI_VERSION, url, error: String(error?.message || error), failedAt: new Date().toISOString() };
    try {
      const toast = hostWindow.toastr || window.toastr;
      if (typeof toast?.error === 'function') toast.error(message, 'Riki 剧情工作台');
      else console.error(message);
    } catch (_) { console.error(message); }
  }
})();
